def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    panels = []
    for r in range(h):
        for c in range(w):
            if not grid[r][c] or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            y0, y1 = min(y for y,x in cells), max(y for y,x in cells)
            x0, x1 = min(x for y,x in cells), max(x for y,x in cells)
            panels.append([row[x0:x1+1] for row in grid[y0:y1+1]])
    return max(panels, key=lambda p: len({v for row in p for v in row}))
